#pragma once

#include "Common.h"

#include <atomic>
#include <juce_audio_formats/juce_audio_formats.h>
#include <juce_dsp/juce_dsp.h>

namespace rh
{
// Builds speaker cabinet impulse responses from a physical-ish description of
// the speaker (resonance, cone breakup, rolloff) and the microphone (position
// across the cone, distance). The result is converted to minimum phase, so the
// cab adds no delay. Every IR is generated by this code: no third-party IRs.
struct CabDescription
{
    const char* name;
    float resonanceHz, resonanceQ;
    float rolloffHz;     // cone rolloff on axis
    int rolloffOrder;    // 2 or 4
    float closedBack;    // 0 open .. 1 sealed (tighter lows, no rear-wave dip)
    struct Peak { float hz, db, q; };
    Peak peaks[6];
    float brightness;    // dust cap presence, dB
    float tweeterDb;     // bass cabs with a horn, 0 = none
    uint32_t seed;       // cone breakup ripple
};

int numCabs();
const CabDescription& cabDescription (int index);

// Returns an IR at the given sample rate. mic: 0 = cap center (bright) .. 1 = cone edge (dark).
// distance: 0 = touching the grille .. 1 = a couple of feet back with some room.
std::vector<float> generateCabIr (int cabIndex, float mic, float distance, double sampleRate);

// Magnitude response of a generated IR, for tests and the UI.
std::vector<float> irMagnitudeDb (const std::vector<float>& ir, double sampleRate, const std::vector<float>& freqs);

class Cabinet : private juce::Thread
{
public:
    Cabinet();
    ~Cabinet() override;

    void prepare (double sampleRate, int maxBlock);
    void reset();
    // Safe to call from the audio thread: IR rebuilds happen on a worker thread.
    void set (int model, float mic, float distance, float lowCutHz, float highCutHz);
    void process (float* x, int n);

    // Loads a user IR file (call from the message thread).
    bool loadUserIr (const juce::File& file);
    juce::String userIrName() const;

    // Offline use: build and install the current IR right now.
    void rebuildNow();
    // A cabinet nobody listens to live (a render, a measurement) needs no worker: its owner
    // calls rebuildNow() when the settings changed. Call before prepare().
    void setOffline (bool o) noexcept { offline = o; }

private:
    void run() override;
    void installIr (std::vector<float> ir);
    void installUserIr();

    juce::dsp::Convolution conv { juce::dsp::Convolution::Latency { 0 } };
    juce::dsp::ProcessSpec spec { 48000.0, 512, 1 };
    double sr = 48000.0;
    std::atomic<int> model { 2 };
    std::atomic<float> mic { 0.3f }, distance { 0.2f };
    std::atomic<bool> pending { false };
    int lastModel = -1;
    float lastMic = -1, lastDist = -1;
    bool userIrLoaded = false;
    juce::String userName;
    juce::AudioBuffer<float> userIr;
    double userIrRate = 48000.0;
    int installedModel = -1;
    Biquad lowCut, highCut;
    float lowHz = 0, highHz = 0;
    bool prepared = false, offline = false;
    juce::CriticalSection userLock;
};
} // namespace rh
